/**
 * ReactDOM 18 Client Reconciliation Engine (Air-Gapped Intranet Distribution)
 * Mounts and reconciles Virtual DOM trees into native DOM nodes with component and SVG support.
 */
(function (global) {
  function createDOMNode(vnode) {
    if (vnode === null || vnode === undefined || vnode === false || vnode === true) {
      return document.createTextNode('');
    }
    if (typeof vnode === 'string' || typeof vnode === 'number') {
      return document.createTextNode(String(vnode));
    }

    // Resolve functional component
    if (typeof vnode.type === 'function') {
      const rendered = vnode.type(vnode.props || {});
      return createDOMNode(rendered);
    }

    if (!vnode.type) {
      return document.createTextNode('');
    }

    const isSVG =
      vnode.type === 'svg' ||
      vnode.type === 'path' ||
      vnode.type === 'line' ||
      vnode.type === 'circle' ||
      vnode.type === 'rect' ||
      vnode.type === 'polyline' ||
      vnode.type === 'polygon' ||
      vnode.type === 'ellipse' ||
      vnode.type === 'g';

    const dom = isSVG
      ? document.createElementNS('http://www.w3.org/2000/svg', vnode.type)
      : document.createElement(vnode.type);

    const props = vnode.props || {};

    for (const [key, value] of Object.entries(props)) {
      if (key === 'children') continue;

      if (key === 'className') {
        if (isSVG) {
          dom.setAttribute('class', value);
        } else {
          dom.className = value;
        }
      } else if (key.startsWith('on') && typeof value === 'function') {
        const eventName = key.slice(2).toLowerCase();
        dom.addEventListener(eventName, value);
      } else if (key === 'style' && typeof value === 'object') {
        Object.assign(dom.style, value);
      } else if (key === 'dangerouslySetInnerHTML' && value && value.__html) {
        dom.innerHTML = value.__html;
      } else if (typeof value === 'boolean') {
        if (value) dom.setAttribute(key, '');
        else dom.removeAttribute(key);
      } else if (value !== undefined && value !== null) {
        dom.setAttribute(key, String(value));
      }
    }

    if (!props.dangerouslySetInnerHTML) {
      const rawChildren = Array.isArray(props.children)
        ? props.children
        : props.children !== undefined
        ? [props.children]
        : [];

      // Flatten nested children recursively
      const flatChildren = rawChildren.flat(Infinity);

      for (const child of flatChildren) {
        if (child !== null && child !== undefined && child !== false && child !== true) {
          dom.appendChild(createDOMNode(child));
        }
      }
    }

    return dom;
  }

  function createRoot(container) {
    let rootComponent = null;

    const instance = {
      render: () => {
        if (!rootComponent) return;

        global.React._setCurrentComponent(rootComponent);
        rootComponent.pendingEffects = [];

        const nextVNode = rootComponent.renderFn();

        // Render to DOM
        container.innerHTML = '';
        container.appendChild(createDOMNode(nextVNode));

        // Flush effects
        const effects = [...rootComponent.pendingEffects];
        rootComponent.pendingEffects = [];
        for (const effect of effects) {
          effect();
        }
      }
    };

    global.React._setRootInstance(instance);

    return {
      render: (element) => {
        if (typeof element.type === 'function') {
          rootComponent = {
            renderFn: () => element.type(element.props || {}),
            hooks: [],
            pendingEffects: []
          };
          instance.render();
        } else {
          container.innerHTML = '';
          container.appendChild(createDOMNode(element));
        }
      }
    };
  }

  global.ReactDOM = { createRoot };
})(window);
